(()=>{
 const cities=[{id:'viscri',title:'Oraș real · Viscri',copy:'Străzi, intersecții și amprentele clădirilor din OpenStreetMap. Aspectul caselor este stilizat în Pixel Drive.'},{id:'original',title:'Oraș original · Pixel Drive',copy:'Cartierul original, păstrat cu traseele, activitățile și regulile existente.'}];
 const style=document.createElement('style');style.textContent=`.city-switch{position:fixed;z-index:20;top:12px;left:12px;border:1px solid #b6c4a6;background:#17261fe8;color:#f3f2df;border-radius:9px;padding:8px 12px;font:600 12px system-ui;cursor:pointer}.city-switch:hover,.city-option:hover{border-color:#e5c16b}.map-credit{position:fixed;z-index:18;left:12px;bottom:10px;padding:4px 7px;border-radius:5px;background:#17261fce;color:#f3f2df;font:11px system-ui}.map-credit a{color:inherit;text-decoration:underline;text-underline-offset:2px}.city-overlay{position:fixed;inset:0;z-index:50;background:#0d1612cc;display:grid;place-items:center;padding:18px}.city-card{width:min(640px,100%);background:#f1eee1;color:#202a23;border:1px solid #c4c2ae;border-radius:18px;padding:26px;box-shadow:0 22px 90px #0008}.city-card h2{margin:0 0 8px;font:800 clamp(24px,5vw,38px)/1.05 system-ui}.city-card>p{margin:0 0 20px;color:#586158;line-height:1.45}.city-options{display:grid;grid-template-columns:1fr 1fr;gap:12px}.city-option{padding:16px;text-align:left;color:#26332a;background:#e7e5d8;border:1px solid #b7b5a6;border-radius:12px;cursor:pointer}.city-option b{display:block;font-size:15px;margin-bottom:8px}.city-option span{display:block;font-size:12px;line-height:1.45}.city-credit{font-size:11px!important;margin:16px 0 0!important;color:#657067!important}.city-credit a{color:#344c3a}.city-overlay[hidden]{display:none}@media(max-width:560px){.city-options{grid-template-columns:1fr}.city-card{padding:20px}}`;
 document.head.append(style);const button=document.createElement('button');button.className='city-switch';button.type='button';button.textContent='Oraș · schimbă';button.setAttribute('aria-label','Schimbă orașul');document.body.append(button);const mapCredit=document.createElement('div');mapCredit.className='map-credit';mapCredit.innerHTML='<a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">© OpenStreetMap contributors · ODbL</a>';document.body.append(mapCredit);
 const overlay=document.createElement('div');overlay.className='city-overlay';overlay.hidden=true;overlay.innerHTML='<section class="city-card" role="dialog" aria-modal="true" aria-labelledby="city-title"><h2 id="city-title">Alege orașul</h2><p>Poți reveni oricând la celălalt oraș. Creditele și mașinile sunt separate; progresul școlii și întrebările rămân comune.</p><div class="city-options"></div><p class="city-credit" data-credit hidden></p></section>';document.body.append(overlay);
 const options=overlay.querySelector('.city-options');for(const city of cities){const b=document.createElement('button');b.className='city-option';b.type='button';b.innerHTML=`<b>${city.title}</b><span>${city.copy}</span>`;b.onclick=()=>{try{localStorage.setItem('pixel-drive-city',city.id);}catch{}location.reload();};options.append(b);}
 const credit=overlay.querySelector('[data-credit]');if(window.DriveWorld?.realMap){credit.hidden=false;credit.innerHTML=`${DriveWorld.mapAttribution} · <a href="${DriveWorld.mapAttributionUrl}" target="_blank" rel="noopener noreferrer">Detalii licență și atribuire</a>`;}
 const hasSavedCity=()=>{try{return!!localStorage.getItem('pixel-drive-city');}catch{return false;}};
 button.onclick=()=>{overlay.hidden=false;};overlay.addEventListener('click',e=>{if(e.target===overlay&&hasSavedCity())overlay.hidden=true;});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!overlay.hidden&&hasSavedCity())overlay.hidden=true;});
 let city='viscri';try{city=localStorage.getItem('pixel-drive-city')||'viscri';}catch{}button.textContent=city==='original'?'Oraș · original':'Oraș · Viscri';mapCredit.hidden=city==='original';if(!hasSavedCity())overlay.hidden=false;
})();
